def load_data():
    citsci = pd.read_csv('/root/data/citsci_train.csv', usecols=['file_rad', 'x', 'y'])
    expert = pd.read_csv('/root/data/expert_train.csv', usecols=['file_rad', 'x', 'y'])
    return citsci, expert

def greedy_match(cluster_centroids, expert_points, max_dist=100):
    if len(cluster_centroids) == 0 or len(expert_points) == 0: return 0, []
    dists = cdist(cluster_centroids, expert_points, metric='euclidean')
    m_e, m_c, matches = set(), set(), []
    flat = sorted([(dists[i,j], i, j) for i in range(len(cluster_centroids)) for j in range(len(expert_points)) if dists[i,j] <= max_dist])
    for d, i, j in flat:
        if i not in m_c and j not in m_e:
            m_c.add(i); m_e.add(j); matches.append(d)
    return len(matches), matches

def evaluate_image(c_pts, e_pts, ms, eps, sw):
    if len(c_pts) == 0: return 0.0, np.nan
    sc = c_pts.copy(); sc[:, 0] *= sw; sc[:, 1] *= (2 - sw)
    db = DBSCAN(eps=eps, min_samples=ms, metric='euclidean').fit(sc)
    centroids = np.array([c_pts[db.labels_ == l].mean(axis=0) for l in set(db.labels_) - {-1}])
    num, m = greedy_match(centroids, e_pts)
    p = num / len(centroids) if len(centroids) > 0 else 0
    r = num / len(e_pts) if len(e_pts) > 0 else 0
    f1 = 2 * p * r / (p + r) if (p + r) > 0 else 0
    return f1, np.mean(m) if m else np.nan

def run_search(params):
    ms, eps, sw, c_g, e_g, files = params
    f1s, ds = [], []
    for f in files:
        f1, d = evaluate_image(c_g.get(f, np.empty((0,2))), e_g.get(f, np.empty((0,2))), ms, eps, sw)
        f1s.append(f1)
        if not np.isnan(d): ds.append(d)
    return (np.mean(f1s), np.mean(ds) if ds else np.nan, ms, eps, sw)

if __name__ == '__main__':
    citsci, expert = load_data()
    c_g = {n: g[['x', 'y']].values for n, g in citsci.groupby('file_rad')}
    e_g = {n: g[['x', 'y']].values for n, g in expert.groupby('file_rad')}
    files = sorted(expert['file_rad'].unique())
    grid = [(ms, eps, round(sw, 1), c_g, e_g, files) for ms in range(3, 10) for eps in range(4, 25, 2) for sw in np.arange(0.9, 1.95, 0.1)]
    with Pool() as p: res = p.map(run_search, grid)
    filt = [r for r in res if r[0] > 0.5]
    if filt:
        costs = np.array([(r[0], r[1]) for r in filt])
        eff = np.ones(len(filt), dtype=bool)
        for i, c in enumerate(costs):
            if eff[i]:
                dom = ((costs[:,0] >= c[0]) & (costs[:,1] <= c[1])) & ((costs[:,0] > c[0]) | (costs[:,1] < c[1]))
                if np.any(dom): eff[i] = False
        pareto = sorted([filt[i] for i in range(len(filt)) if eff[i]], key=lambda x: (-x[0], x[1]))
        with open('/root/pareto_frontier.csv', 'w') as f:
            f.write("F1,delta,min_samples,epsilon,shape_weight\n")
            for r in pareto: f.write(f"{r[0]:.5f},{r[1]:.5f},{r[2]},{r[3]},{r[4]:.1f}\n")
